using namespace std;

class Solution {
public:
    vector<int> findDiameterEndpoints(int n, vector<vector<int>>& edges) {
        if (n == 1) return {0, 0};
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto bfs = [&](int start) -> pair<int, vector<int>> {
            vector<int> dist(n, -1);
            dist[start] = 0;
            queue<int> q;
            q.push(start);
            int farthest = start;
            while (!q.empty()) {
                int curr = q.front();
                q.pop();
                if (dist[curr] > dist[farthest] || (dist[curr] == dist[farthest] && curr < farthest)) {
                    farthest = curr;
                }
                for (int nxt : adj[curr]) {
                    if (dist[nxt] == -1) {
                        dist[nxt] = dist[curr] + 1;
                        q.push(nxt);
                    }
                }
            }
            return {farthest, dist};
        };
        int u = bfs(0).first;
        int v = bfs(u).first;
        return {min(u, v), max(u, v)};
    }
};

import java.util.*;

class Solution {
    public int[] findDiameterEndpoints(int n, int[][] edges) {
        if (n == 1) return new int[]{0, 0};
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int u = bfs(0, n, adj);
        int v = bfs(u, n, adj);
        return new int[]{Math.min(u, v), Math.max(u, v)};
    }

    private int bfs(int start, int n, List<List<Integer>> adj) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        int farthest = start;
        while (!q.isEmpty()) {
            int curr = q.poll();
            if (dist[curr] > dist[farthest] || (dist[curr] == dist[farthest] && curr < farthest)) {
                farthest = curr;
            }
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.offer(nxt);
                }
            }
        }
        return farthest;
    }
}

var findDiameterEndpoints = function(n, edges) {
    if (n === 1) return [0, 0];
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    function bfs(start) {
        const dist = new Array(n).fill(-1);
        dist[start] = 0;
        const q = [start];
        let farthest = start;
        while (q.length > 0) {
            const curr = q.shift();
            if (dist[curr] > dist[farthest] || (dist[curr] === dist[farthest] && curr < farthest)) {
                farthest = curr;
            }
            for (const nxt of adj[curr]) {
                if (dist[nxt] === -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.push(nxt);
                }
            }
        }
        return farthest;
    }
    const u = bfs(0);
    const v = bfs(u);
    return [Math.min(u, v), Math.max(u, v)];
};
